-- Immutable Giving audit trail. Financial changes are logged by database trigger; authenticated users receive read-only access through RLS.
create table public.giving_audit_events(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,entity_type text not null check(entity_type in ('fund','contribution')),entity_id uuid not null,action text not null,actor_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index giving_audit_church_created_idx on public.giving_audit_events(church_id,created_at desc);
alter table public.giving_audit_events enable row level security; alter table public.giving_audit_events force row level security;
create policy "giving audit finance read" on public.giving_audit_events for select to authenticated using(private.has_church_role(church_id,array['owner','pastor','administrator','finance']::public.church_role[]));
revoke all on public.giving_audit_events from anon,authenticated; grant select on public.giving_audit_events to authenticated;
create or replace function private.audit_giving_changes() returns trigger language plpgsql security definer set search_path='' as $$ declare cid uuid; eid uuid; act text; meta jsonb:='{}'::jsonb; begin cid:=coalesce(new.church_id,old.church_id); eid:=coalesce(new.id,old.id); act:=lower(tg_op); if tg_table_name='contributions' then meta:=jsonb_build_object('status_before',case when tg_op='INSERT' then null else old.status::text end,'status_after',case when tg_op='DELETE' then null else new.status::text end,'amount_before',case when tg_op='INSERT' then null else old.amount end,'amount_after',case when tg_op='DELETE' then null else new.amount end); elsif tg_table_name='giving_funds' then meta:=jsonb_build_object('active_before',case when tg_op='INSERT' then null else old.is_active end,'active_after',case when tg_op='DELETE' then null else new.is_active end); end if; insert into public.giving_audit_events(church_id,entity_type,entity_id,action,actor_id,metadata) values(cid,case when tg_table_name='contributions' then 'contribution' else 'fund' end,eid,act,(select auth.uid()),meta); return coalesce(new,old); end $$;
create trigger audit_contributions after insert or update or delete on public.contributions for each row execute function private.audit_giving_changes();
create trigger audit_giving_funds after insert or update or delete on public.giving_funds for each row execute function private.audit_giving_changes();